### `main.go`

```go
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
)

// StateIn is one streamed capsule motion. The capsule is a segment [p0,p1]
// with radius r. Endpoints move linearly, which expresses linear translation
// plus interpolated angular motion of the capsule axis.
type StateIn struct {
	ID      int        `json:"id"`
	Radius  float64    `json:"radius"`
	P0Start [3]float64 `json:"p0_start"`
	P1Start [3]float64 `json:"p1_start"`
	P0End   [3]float64 `json:"p0_end"`
	P1End   [3]float64 `json:"p1_end"`
}

type VerifyOut struct {
	Before *float64 `json:"before"`
	After  float64  `json:"after"`
	OK     bool     `json:"ok"`
}

type ResultOut struct {
	ID             int        `json:"id"`
	TimeOfImpact   float64    `json:"time_of_impact"`
	Normal         [3]float64 `json:"normal"`
	TriangleID     int        `json:"triangle_id"`
	Classification string     `json:"classification"`
	Verify         *VerifyOut `json:"verify,omitempty"`
}

type MeshFile struct {
	Triangles [][3][3]float64 `json:"triangles"`
}

func vec3From(f [3]float64) Vec3 { return V(f[0], f[1], f[2]) }

func vec3To(v Vec3) [3]float64 { return [3]float64{v.X, v.Y, v.Z} }

func loadMesh(path string) (*Mesh, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var mf MeshFile
	if err := json.Unmarshal(data, &mf); err != nil {
		return nil, err
	}
	m := &Mesh{}
	for _, t := range mf.Triangles {
		m.Tris = append(m.Tris, Triangle{vec3From(t[0]), vec3From(t[1]), vec3From(t[2])})
	}
	if len(m.Tris) == 0 {
		return nil, fmt.Errorf("mesh %q has no triangles", path)
	}
	return m, nil
}

func main() {
	meshPath := flag.String("mesh", "", "mesh JSON file (default: built-in 0.01-thick wall)")
	verify := flag.Bool("verify", false, "re-check every hit by sampling signed clearance before/after")
	tol := flag.Float64("tol", 1e-9, "time-of-impact accuracy")
	restTol := flag.Float64("rest-tol", 1e-7, "same-contact time threshold")
	inPath := flag.String("in", "-", "input JSONL path ('-' for stdin)")
	dumpMesh := flag.Bool("dumpmesh", false, "print the active mesh as JSON and exit")
	flag.Parse()

	var mesh *Mesh
	if *meshPath == "" {
		mesh = BuildThinWall(0.01, 1.0, 1.0)
	} else {
		m, err := loadMesh(*meshPath)
		if err != nil {
			fmt.Fprintln(os.Stderr, "mesh error:", err)
			os.Exit(2)
		}
		mesh = m
	}

	if *dumpMesh {
		var mf MeshFile
		for _, tr := range mesh.Tris {
			mf.Triangles = append(mf.Triangles, [3][3]float64{vec3To(tr.A), vec3To(tr.B), vec3To(tr.C)})
		}
		if err := json.NewEncoder(os.Stdout).Encode(mf); err != nil {
			fmt.Fprintln(os.Stderr, "dump error:", err)
			os.Exit(4)
		}
		return
	}

	solver := &Solver{Mesh: mesh, Tol: *tol}

	var in io.Reader = os.Stdin
	if *inPath != "-" {
		f, err := os.Open(*inPath)
		if err != nil {
			fmt.Fprintln(os.Stderr, "input error:", err)
			os.Exit(2)
		}
		defer f.Close()
		in = f
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	enc := json.NewEncoder(out)

	sc := bufio.NewScanner(in)
	sc.Buffer(make([]byte, 0, 1<<20), 1<<24)

	ctx := streamCtx{prevTri: -1}
	for sc.Scan() {
		line := sc.Bytes()
		if len(trimSpace(line)) == 0 {
			continue
		}
		var st StateIn
		if err := json.Unmarshal(line, &st); err != nil {
			fmt.Fprintln(os.Stderr, "bad JSON line:", err)
			os.Exit(3)
		}
		res := solveState(solver, st, *verify, *restTol, &ctx)
		if err := enc.Encode(res); err != nil {
			fmt.Fprintln(os.Stderr, "write error:", err)
			os.Exit(4)
		}
	}
	if err := sc.Err(); err != nil {
		fmt.Fprintln(os.Stderr, "read error:", err)
		os.Exit(5)
	}
}

type streamCtx struct {
	prevContact bool
	prevTri     int
}

func solveState(s *Solver, st StateIn, doVerify bool, restTol float64, ctx *streamCtx) ResultOut {
	a0, b0 := vec3From(st.P0Start), vec3From(st.P1Start)
	a1, b1 := vec3From(st.P0End), vec3From(st.P1End)
	res := s.TimeOfImpact(a0, b0, a1, b1, st.Radius)

	out := ResultOut{ID: st.ID, TimeOfImpact: -1, TriangleID: -1, Classification: "none"}
	if !res.Hit {
		ctx.prevContact = false
		ctx.prevTri = -1
		return out
	}

	out.TimeOfImpact = res.T
	out.TriangleID = res.TriID
	out.Normal = vec3To(res.Normal)

	// A state that starts already in contact with the same triangle as the
	// previous state is a continuation (resting) contact, not a new impact.
	if res.T <= restTol && ctx.prevContact && ctx.prevTri == res.TriID {
		out.Classification = "resting"
	} else {
		out.Classification = "impact"
	}

	// Determine whether the capsule is still in contact at the end of the step
	// (persistent contact), which lets the next state recognise a resting
	// contact even when its reported TOI is numerically ~0.
	atEnd, _, _, endTri, _ := s.eval(a0, b0, a1, b1, st.Radius, 1)
	if atEnd <= restTol {
		ctx.prevContact = true
		ctx.prevTri = endTri
	} else {
		ctx.prevContact = false
		ctx.prevTri = -1
	}

	if doVerify {
		v := s.Verify(a0, b0, a1, b1, st.Radius, res.T)
		vo := &VerifyOut{After: v.After, OK: v.OK}
		if v.Before != nil {
			vo.Before = v.Before
		}
		out.Verify = vo
	}
	return out
}

func trimSpace(b []byte) []byte {
	start := 0
	for start < len(b) && (b[start] == ' ' || b[start] == '\t' || b[start] == '\r' || b[start] == '\n') {
		start++
	}
	end := len(b)
	for end > start && (b[end-1] == ' ' || b[end-1] == '\t' || b[end-1] == '\r' || b[end-1] == '\n') {
		end--
	}
	return b[start:end]
}
